<label className="font-semibold text-sm">Lokasi / cabang<textarea className="textarea textarea-bordered w-full mt-1 bg-white text-slate-900" rows={2} maxLength={160} required value={receiptSettings.location} onChange={e=>setReceiptSettings(v=>({...v,location:e.target.value}))}/></label>
